import{z as o,x as s,o as l,c as p,q as A,j as r,D as e,d as t,s as B,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"侧壁角","description":"","frontmatter":{"title":"侧壁角","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/sidewall-angle.md","filePath":"litho/sidewall-angle.md","lastUpdated":1791063341000}'),D={name:"litho/sidewall-angle.md"};function d(h,a,C,m,c,u){const i=s("Mermaid");return l(),p("div",null,[a[2]||(a[2]=A('<h1 id="侧壁角" tabindex="-1">侧壁角 <a class="header-anchor" href="#侧壁角" aria-label="Permalink to &quot;侧壁角&quot;">​</a></h1><div class="epigraph"><p>顶视 CD 合格，剖面仍可以是锥或倒锥；刻蚀看见的是这张斜面，转印后的底宽不必等于胶顶宽。</p><footer>—— 据 Levinson 对抗蚀剂剖面与刻蚀转印的讨论整理</footer></div><p><a href="/litho/standing-wave-barc">上一课</a>用 BARC 压掉驻波波纹，侧壁不再按 \\(\\lambda/(2n)\\) 起皱。缺口是：平均剖面角还在——吸收、显影前沿与 PEB 仍会给出锥形或倒锥。本课钉侧壁角。图形何时成对弯倒、别把它误诊成什么，留给<a href="/litho/pattern-collapse">下一课</a>；金属氧化物胶与 CAR 的分叉，是后面的<a href="/litho/euv-resist">金属氧化物胶 vs 化学放大胶</a>一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ADI 顶视 CD 是某一焦平面（或算法认定的）宽度。刻蚀等离子体打的是三维浮雕：顶宽、底宽、残胶、圆角。侧壁角 \\(\\theta\\)（相对衬底）决定横向还有多少胶可被打掉、底宽相对顶宽如何走。<a href="/litho/adi-aei">ADI 对 AEI</a> 已经要求两套 CD 分开报；本课补的是偏置的几何来源之一：斜面，而不只是「腔室吃掉几个纳米」。</p><p>理想 \\(\\theta=90^\\circ\\)。正锥（\\(\\theta\\lt 90^\\circ\\)，底比顶宽或顶比底宽，视定义）让刻蚀后底 CD 与胶顶 CD 系统偏离。倒锥（倒八字）容易塌、去胶难、局部阴影。把所有 AEI 偏置写成微负载，会漏掉当天 PEB 或吸收把角走掉的情况。</p><p><span class="marginnote">数字实例：胶厚 100 nm、\\(\\theta=85^\\circ\\) 时，顶底宽度差约为 \\(100\\times\\cot 85^\\circ\\approx 9\\) nm。两片顶视 CD 完全相同的胶，剖面角差这 5° 就能让 AEI 底宽差出近 10 nm——这正是顶视计量看不出的问题。</span></p><h3 id="波纹被压平不等于直角" tabindex="-1">波纹被压平不等于直角 <a class="header-anchor" href="#波纹被压平不等于直角" aria-label="Permalink to &quot;波纹被压平不等于直角&quot;">​</a></h3><p>BARC 去掉的是高频 \\(z\\) 振荡。体吸收（上部剂量高于底部，或相反）给出缓慢的锥。显影时间过长，边沿被暗侵蚀修成喇叭。PEB 的横向扩散把阈值轮廓外推，角也会变。这些是平均几何，不是 LCDU。</p><p><span class="marginnote">侧壁角的计量要剖面 SEM 或 AFM/散射测量，不能从顶视 CD 反推唯一的 \\(\\theta\\)。同一顶宽可以配许多剖面。OPC 若只拟合顶视，刻蚀模型会把角的误差当成各向异性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>表征：裂片或 X-SEM 量顶、底、角；工艺窗除 CD 外把 \\(\\theta\\) 与残胶列为判据。E–D 窗若只切顶视 CD，边沿可能已经倒锥。控制：胶厚与吸收（Dill B、PAG 吸收）、PEB、显影时间、BARC 是否清底。Focus drilling 把多张离焦像叠起来，等效 NILS 下降，角往往更差——成像课末尾的走焦在这里兑现在剖面上。过显影修圆角、吃暗区，顶视 CD 还能用剂量拧回来，角已经走了，AEI 不会跟着顶视走。</p><p>刻蚀转移：各向异性好时，胶斜面仍会在硬掩模上留下与剩余厚度、选择比有关的偏置。选择比不够，斜面被打薄，底 CD 跟着重影。转印函数必须吃 \\(\\theta\\)，不能只吃 ADI 均值。</p><h3 id="与-的衔接" tabindex="-1">与 \\(R(m)\\) 的衔接 <a class="header-anchor" href="#与-的衔接" aria-label="Permalink to &quot;与 $R(m)$ 的衔接&quot;">​</a></h3><p>Mack / Notch 的陡度 \\(n\\) 大，前沿更贴着等 \\(m\\) 面，角更直，同时对驻波残差更敏感。BARC 把 \\(I(z)\\) 拉平，角才主要由横向 ILS 与 \\(R(m)\\) 决定。两课是串起来的：先减反，再谈平均角。</p>',15)),(l(),r(n,null,{default:e(()=>[B(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROF%5B%22%E8%83%B6%E5%89%96%E9%9D%A2%E8%A7%92%20%CE%B8%22%5D%20--%3E%20ET%5B%22%E5%88%BB%E8%9A%80%E8%BD%AC%E5%8D%B0%22%5D%0A%20%20ADI%5B%22%E9%A1%B6%E8%A7%86%20ADI%20CD%22%5D%20--%3E%20ET%0A%20%20ET%20--%3E%20AEI%5B%22AEI%20%E5%BA%95%E5%AE%BD%22%5D%0A%20%20ABS%5B%22%E5%90%B8%E6%94%B6%20%2F%20PEB%20%2F%20%E6%98%BE%E5%BD%B1%22%5D%20--%3E%20PROF%0A%20%20BARC%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%87%8F%E5%8F%8D%22%5D%20--%3E%20PROF%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"正胶若顶部吸收强、底部剂量不足，底部转化不够，显影后容易出现正锥（底部更宽的胶墙，或清不干净）。漂白（DNQ）或部分透明可以缓解。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"T-top 可以想象成蘑菇头：表面层被曝光副产物「淬硬」、变得最难溶，显影液从两侧把腰部掏空，留下上宽下窄的倒八字开口——倒锥加残胶常常一起出现。"),t("CAR 薄膜、BARC 之后，角更多由边缘 ILS、酸横向扩散与过显影决定。倒锥常见于表面难溶（T-top、表面淬灭）：顶部阈值高，腰部先溶。表面难溶与 BARC 不足可以同时存在：波纹叠在倒锥上，X-SEM 要能分开「高频皱」与「平均角」。")],-1)),a[6]||(a[6]=E("p",null,"刻蚀时，离子方向相对斜面有一入射角，溅射产额与聚合物沉积随角变，所以同一腔室、不同 \\(\\theta\\) 的来料，AEI 不同。侧壁角因此是光刻交给刻蚀的边界条件，不是镜头 NA 的别名。硬掩模可以「冻结」某一剖面再往下走，但冻结的是已经斜了的开口，不是把角纠正回 90°。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"常见误区：以为刻蚀能「修直」斜面。实际上硬掩模只是把已经斜了的开口继续向下转印，角度不会被纠正，只会被选择比保真或放大——上游角走了 2°，下游硬掩模和衬底上通常还是那 2°。")],-1)),(l(),r(n,null,{default:e(()=>[B(i,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%A1%B6%E9%83%A8%E5%90%B8%E6%94%B6%E5%BC%BA%20%2F%20%E5%BA%95%E9%83%A8%E5%89%82%E9%87%8F%E4%B8%8D%E8%B6%B3%22%5D%20--%3E%20B%5B%22%E5%BA%95%E9%83%A8%E8%BD%AC%E5%8C%96%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%AD%A3%E9%94%A5%EF%BC%9A%E5%BA%95%E6%9B%B4%E5%AE%BD%E6%88%96%E6%B8%85%E4%B8%8D%E5%87%80%22%5D%0A%20%20D%5B%22%E8%A1%A8%E9%9D%A2%E6%B7%AC%E7%81%AD%20%2F%20T-top%22%5D%20--%3E%20E%5B%22%E9%A1%B6%E9%83%A8%E9%98%88%E5%80%BC%E5%81%8F%E9%AB%98%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%85%B0%E9%83%A8%E5%85%88%E6%BA%B6%EF%BC%9A%E5%80%92%E9%94%A5%22%5D%0A%20%20G%5B%22%E8%BF%87%E6%98%BE%E5%BD%B1%20%2F%20%E9%85%B8%E6%A8%AA%E5%90%91%E6%89%A9%E6%95%A3%22%5D%20--%3E%20H%5B%22%E8%BE%B9%E6%B2%BF%E4%BF%AE%E5%9C%86%E6%88%96%E5%96%87%E5%8F%AD%E5%8F%A3%22%5D%0A%20%20C%20--%3E%20I%5B%22%E5%90%8C%E4%B8%80%E9%A1%B6%E8%A7%86%20CD%EF%BC%8C%E5%89%96%E9%9D%A2%E4%B8%8D%E5%90%8C%22%5D%0A%20%20F%20--%3E%20I%0A%20%20H%20--%3E%20I%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=A('<p><span class="marginnote">负胶或 NTD 的「留下区」在曝光区，吸收与表面效应的符号会反。角的判据仍是转印，不要把正胶的锥形口令抄过去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某家 RIE 的射频功率表，不把 FinFET 鳍的角度规格当成光刻胶角的同义词——器件侧壁是后续多次转印的结果。EUV 随机缺失是孔的有无，不是平均 \\(\\theta\\)；后面换记录介质时，角与随机要分开报。</p><p>不要发明「\\(\\theta\\gt 85^\\circ\\) 则良率 99%」的换算。出处里的 Levinson 把剖面当作转印输入，具体合格区由工艺包定。抗蚀剂化学主干到 CAR 的平均剖面为止；金属氧化物是另一套溶解/交联，角要重测。</p><p>顶视 CD 可以用剂量拧；角往往要用吸收、PEB 或显影时间。两个执行器不要抢同一个 SEM 数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>侧壁角是浮雕几何；顶视 CD 不能唯一决定它。</li><li>BARC 压波纹之后，吸收、PEB、显影仍给出平均锥或倒锥。</li><li>刻蚀偏置吃 \\(\\theta\\) 与选择比，AEI 底宽不必等于 ADI 顶宽。</li><li>倒锥常见于表面淬灭 / T-top；正锥常见于底部剂量不足。</li><li>后面的 EUV 换胶课比较 CAR 与金属氧化物胶，默认本课的剖面语言仍适用。</li><li>出处：Levinson, <em>Principles of Lithography</em>；Mack 对显影剖面与转印的讨论。</li></ul>',7))])}const P=o(D,[["render",d]]);export{F as __pageData,P as default};
